CREATE TABLE `iot_collect_data` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `cid` bigint NOT NULL COMMENT '任务执行标识',
  `uid` bigint DEFAULT NULL COMMENT '设备uid',
  `signal_id` bigint NOT NULL COMMENT '信号id',
  `field_type` tinyint DEFAULT NULL COMMENT '数据类型',
  `collect_task_id` bigint NOT NULL COMMENT '任务id',
  `address` varchar(128) DEFAULT NULL COMMENT '信号地址',
  `value` varchar(256) DEFAULT NULL COMMENT '值',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '采集状态',
  `reason` varchar(64) NOT NULL DEFAULT '' COMMENT '错误说明',
  `collect_time` datetime NOT NULL COMMENT '采集时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `iot_collect_data_cid_index` (`cid` DESC),
  KEY `iot_collect_data_collect_time_index` (`collect_time` DESC),
  KEY `iot_collect_data_signal_id_index` (`signal_id`),
  KEY `iot_collect_data_uid_index` (`uid` DESC)
) ENGINE=InnoDB AUTO_INCREMENT=543 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='采集到的数据';
